# Midnight Witness pilot: The Golden State Killer
# Each segment: (scene, params, narration)
TITLE = "The Golden State Killer"
CH = []  # chapters filled by builder: (segment index, chapter name)

S = []
def seg(scene, text, **p):
    S.append((scene, p, text.strip()))
def chapter(name, sub):
    S.append(("chapter", {"title": name, "sub": sub}, ""))

# ---------- COLD OPEN ----------
seg("house", "April 24th, 2018. Citrus Heights, California. A quiet street of tidy lawns, two-car garages and basketball hoops.", day=True, caption="CITRUS HEIGHTS, CA  •  APRIL 24, 2018")
seg("house", "Inside one of these houses lives a seventy-two-year-old grandfather. A retired truck mechanic. A Navy veteran. The kind of neighbour you wave at and forget.", day=True)
seg("surveil", "But for days, unmarked cars have been watching this house. Detectives have been following this man wherever he goes.", stamp="SURVEILLANCE")
seg("surveil", "That afternoon, he steps out into his side yard, in a T-shirt, cargo shorts and tube socks. And a team of armed deputies moves in.", stamp="15:42  SUBJECT EXITS RESIDENCE")
seg("quote", "He doesn't run. He doesn't fight. He only protests, in a high, startled voice:", q="")
seg("quote", "I have a roast in the oven.", q="“I have a roast in the oven.”", who="AT THE MOMENT OF ARREST")
seg("stats", "For more than forty years, this man had been one of the most wanted criminals in American history. At least thirteen murders. More than fifty rapes. Countless burglaries, across eleven California counties.", items=[["13","MURDERS"],["50+","RAPES"],["11","COUNTIES"]])
seg("evidence", "He had worn a ski mask. He had left no fingerprints. Almost no one who saw him lived to describe him, and those who did could only describe the mask.", items=[["mask","Ski mask (description)"],["flashlight","Flashlight"],["rope","Shoelace bindings"]])
seg("dna", "And yet in the end, he was not caught by a witness, or a confession, or a lucky traffic stop. He was caught by a family tree, built from the DNA of strangers who had never heard his name.")
seg("title", "This is the story of the Golden State Killer. And of the people who refused to let him disappear into the dark.", big="THE GOLDEN STATE KILLER", small="MIDNIGHT WITNESS PRESENTS")

# ---------- CH1 ----------
chapter("Chapter One", "The Ransacker")
seg("map", "Before he had a name, he was a pattern. In 1974, in the farming town of Visalia, in California's Central Valley, homes started being broken into in a very strange way.", pins=[["Visalia",1]], focus="visalia", title="VISALIA  •  1974")
seg("file", "Almost nothing of value was taken. Instead, the burglar would go through drawers, scatter women's clothing across the floor, take small things like coins, piggy banks, single earrings, photographs. Sometimes he hit several houses in a single night.", head="VISALIA PD  •  BURGLARY SERIES 1974-75", lines=["Entry: rear window / sliding door","Items taken: coins, piggy banks, single earrings","Women's clothing scattered","Multiple homes hit in one night"])
seg("board", "Police nicknamed him the Visalia Ransacker. Over about two years, dozens of homes were hit. On November 30th, 1974, he broke into twelve houses in a single day.", cards=["VISALIA RANSACKER","12 HOMES IN ONE DAY","NOV 30, 1974","NO PRINTS"])
seg("house", "Then, on the night of September 11th, 1975, it stopped being about burglary.", caption="VISALIA, CA  •  SEPT 11, 1975", rain=True)
seg("house", "Claude Snelling, a forty-five-year-old journalism professor, woke to sounds outside. A masked man was dragging his sixteen-year-old daughter out of the house.", figure=True)
seg("file", "Snelling ran out to stop him. The intruder shot him, kicked the girl in the face, and fled into the night. Claude Snelling died protecting his daughter.", head="HOMICIDE  •  CLAUDE SNELLING, 45", lines=["Victim confronted intruder abducting daughter","Shot by the intruder","Suspect fled on foot","Daughter survived"])
seg("surveil", "Three months later, in December 1975, a detective named William McGowen was staking out a house the Ransacker had targeted before. A figure in a ski mask appeared in the dark.", stamp="STAKEOUT  •  DEC 12, 1975")
seg("surveil", "McGowen chased him. The man fired at the detective, and vanished over a fence. After that night, the Visalia Ransacker was never seen there again.", stamp="SUSPECT FLED")
seg("map", "Ten miles away, in the small town of Exeter, a young police officer worked in the burglary unit. His name was Joseph James DeAngelo. In 1976, he took a new job, at a police department near Sacramento.", pins=[["Visalia",0],["Exeter",1],["Auburn",1]], focus="valley", title="CENTRAL VALLEY  •  1976")

# ---------- CH2 ----------
chapter("Chapter Two", "The East Area Rapist")
seg("map", "In June 1976, two months before that officer started his new job in Auburn, a new nightmare began in the eastern suburbs of Sacramento.", pins=[["Rancho Cordova",1],["Carmichael",1],["Citrus Heights",1],["Sacramento",0]], focus="sac", title="EAST AREA  •  1976-1979", route=False)
seg("photos", "The attacks followed a pattern so precise it felt rehearsed. He chose quiet, middle-class neighbourhoods near open fields, creeks and parks, places where a man on foot could disappear in seconds.", photos=[["street","Quiet suburb"],["field","Open field"],["window","Point of entry"]])
seg("phone", "He studied his victims for weeks. Many received strange phone calls before an attack: someone silent on the line, breathing, then hanging up. He was learning their routines.", txt="* RING *")
seg("house", "He came in through windows and sliding doors in the middle of the night. He woke his victims with a flashlight in their eyes and a gun in his hand, wearing a mask. He tied them up and terrorised them for hours.", beam=True)
seg("board", "At first he attacked women who were alone. Then he began attacking couples. He would tie up the man and stack dishes on his back, warning that if he heard a plate rattle, he would kill everyone in the house.", cards=["SKI MASK","FLASHLIGHT","SHOELACE BINDINGS","DISHES ON BACK","PRE-ATTACK PHONE CALLS"])
seg("file", "He often stayed in the house long after the assault, eating food from the kitchen, wandering through the rooms, while his victims lay in the dark not knowing if he was still there.", head="EAST AREA RAPIST  •  MODUS OPERANDI", lines=["Prowling for weeks before attacks","Unlocks windows in advance","Hides ligatures in the home","Remains in house for hours","Escapes on foot or bicycle"])
seg("newspaper", "The newspapers called him the East Area Rapist. Fear swept through Sacramento. People slept with shotguns. Families bought guard dogs. Locksmiths and gun shops could barely keep up.", head="EAST AREA RAPIST STRIKES AGAIN", sub="Residents arm themselves as attacks continue")
seg("quote", "In December 1976, he attacked a fifteen-year-old girl named Kris Pedretti in Carmichael. Her account of that night is the source of a chilling phrase, I'll be gone in the dark, that would later become the title of the most famous book ever written about him.", q="“I'll be gone in the dark.”", who="THE THREAT THAT BECAME A BOOK TITLE")
seg("phone", "He also liked to call back. One victim picked up her phone long after her attack and heard a male voice say: Merry Christmas. It's me again. Then the line went dead.", txt="“IT'S ME AGAIN.”")
seg("newspaper", "In December 1977, a rambling poem was mailed to the Sacramento Bee newspaper, the mayor's office and a local TV station. Investigators believed it came from him. He was taunting the entire city.", head="POEM SENT TO CITY OFFICIALS", sub="Police believe letter is from the East Area Rapist")
seg("board", "Police threw everything at the case. Hundreds of suspects were questioned. Some were followed for months, then cleared. Witnesses gave only a vague description of a young white man with a slim build. But never a face.", cards=["HUNDREDS OF LEADS","SUSPECTS CLEARED","NO FINGERPRINTS","NO FACE"])
seg("photos", "And then, on the night of February 2nd, 1978, he killed again.", photos=[["street","Rancho Cordova"],["road","Feb 2, 1978"]])
seg("file", "Brian and Katie Maggiore, a young married couple, were walking their dog through their Rancho Cordova neighbourhood. They saw something, or someone, they were not supposed to see.", head="HOMICIDE  •  BRIAN & KATIE MAGGIORE", lines=["Young couple walking their dog","Chased through neighbourhood yards","Both shot to death","Witnesses saw a young man fleeing"])
seg("sketch", "They ran. The attacker chased them through backyards and shot them both dead. Witnesses described a young man running from the scene. Police drew composite sketches. Nobody recognised him.")
seg("newspaper", "The killing of the Maggiores changed everything. The East Area Rapist was now also a murderer, and he was willing to kill anyone who saw him. Neighbourhood watch meetings filled school gyms. Hundreds of residents crowded into town halls demanding answers.", head="COUPLE SHOT WHILE WALKING DOG", sub="Rancho Cordova residents fear link to serial attacker")
seg("map", "The attacks spread beyond Sacramento, to Stockton, Modesto, Davis, and then into the San Francisco Bay Area: Walnut Creek, Danville, Fremont, San Ramon. Fifty attacks across seven counties in three years.", pins=[["Sacramento",0],["Davis",1],["Stockton",1],["Modesto",1],["Walnut Creek",1],["Danville",1],["Fremont",1]], focus="norcal", title="NORTHERN CALIFORNIA  •  50 ATTACKS")

# ---------- CH3 ----------
chapter("Chapter Three", "The Cop")
seg("badge", "While all this was happening, Joseph DeAngelo was wearing a police badge in Auburn, a small city just northeast of Sacramento. Colleagues later described him as unremarkable. A little odd. Someone who stood too close when he talked to you.")
seg("file", "So who was this man? Joseph James DeAngelo Jr. was born on November 8th, 1945, in Bath, New York. His father was an Army sergeant. According to court records and later reporting, his childhood was violent: both parents beat him, and while the family lived in West Germany he witnessed a horrific assault on one of his sisters.", head="SUBJECT PROFILE  \u2022  J.J. DeANGELO JR.", lines=["Born: Nov 8, 1945, Bath, New York","Father: U.S. Army sergeant","Childhood: West Germany, then California","Folsom High School, GED 1964"])
seg("file", "As a teenager in the Sacramento area, prosecutors say he was already committing burglaries and torturing animals. In 1964 he joined the Navy and served during the Vietnam War, aboard the cruiser USS Canberra.", head="SUBJECT PROFILE  \u2022  SERVICE RECORD", lines=["U.S. Navy, Sept 1964","Damage controlman, 22 months","USS Canberra / USS Piedmont","Vietnam War era"])
seg("file", "Back home, he studied police science, then earned a bachelor's degree in criminal justice from Sacramento State. He learned exactly how detectives think, how crime scenes are processed, and how investigations fall apart.", head="SUBJECT PROFILE  \u2022  EDUCATION", lines=["Sierra College: A.A. Police Science","Sacramento State: B.A. Criminal Justice","Joined Exeter PD: May 1973","Burglary unit"])
seg("quote", "In 1970 he was engaged to a nursing student named Bonnie Colwell. She ended the relationship after he became controlling and abusive, and he later threatened her with a gun. Years later, one investigator would suggest that anger toward her may have fuelled some of his crimes.", q="A BROKEN ENGAGEMENT", who="1970 \u2013 1971")
seg("file", "In July 1979, DeAngelo was caught shoplifting from a Pay N' Save store in Citrus Heights. What he tried to steal was strange: a hammer, and a can of dog repellent.", head="ARREST REPORT  •  JULY 1979", lines=["Suspect: J. DeAngelo (Auburn PD officer)","Location: Pay N' Save, Citrus Heights","Items: 1 hammer, 1 can dog repellent","Disposition: 6 months probation"])
seg("quote", "When he was caught, he reportedly faked a heart attack, then acted as if he had lost his mind, before admitting it was all an act. In October 1979, the Auburn Police Department fired him.", q="DISMISSED FROM AUBURN PD", who="OCTOBER 1979")
seg("timeline", "Think about the timing. The last East Area Rapist attack in Northern California happened on July 5th, 1979, in Danville. That same month, the officer who would one day be named as the attacker was arrested for shoplifting.", marks=[["1976","EAR begins"],["JUL 5 1979","Last NorCal attack"],["JUL 1979","DeAngelo arrested"],["OCT 1979","DeAngelo fired"]])
seg("dog", "Investigators would later wonder: was the dog repellent meant for the family dogs that Sacramento residents had bought to protect themselves from him?")
seg("house", "Six weeks after the shoplifting arrest, his first daughter was born. On paper, he looked like a man settling down. In reality, he had simply moved his hunting ground hundreds of miles south.")

# ---------- CH4 ----------
chapter("Chapter Four", "The Original Night Stalker")
seg("map", "On October 1st, 1979, in Goleta, a beach town near Santa Barbara, a masked intruder tied up a couple in their home. The woman screamed, and he ran. It was a warning of what was coming.", pins=[["Goleta",1],["Santa Barbara",0]], focus="socal", title="GOLETA  •  OCTOBER 1979", route=False)
seg("file", "On December 30th, 1979, also in Goleta, Dr. Robert Offerman and Dr. Debra Manning were found shot to death in Offerman's condominium.", head="HOMICIDE  •  OFFERMAN / MANNING", lines=["Goleta, CA  •  Dec 30, 1979","Both victims bound","Both shot","Same pattern as the October attack"])
seg("file", "On March 13th, 1980, in Ventura, attorney Lyman Smith and his wife Charlene were murdered in their home. They were bound and beaten. Their bodies were discovered by Lyman's twelve-year-old son.", head="HOMICIDE  •  LYMAN & CHARLENE SMITH", lines=["Ventura, CA  •  Mar 13, 1980","Both victims bound","Found by 12-year-old son"])
seg("file", "On August 19th, 1980, in Dana Point, newlyweds Keith and Patrice Harrington were killed in their home. They had been married for just three months.", head="HOMICIDE  •  KEITH & PATRICE HARRINGTON", lines=["Dana Point, CA  •  Aug 19, 1980","Married three months","Discovered by Keith's father"])
seg("file", "On February 6th, 1981, in Irvine, twenty-eight-year-old Manuela Witthuhn was killed in her home while her husband was in hospital.", head="HOMICIDE  •  MANUELA WITTHUHN, 28", lines=["Irvine, CA  •  Feb 6, 1981","Victim home alone","Husband hospitalised at the time"])
seg("file", "On July 27th, 1981, back in Goleta, Cheri Domingo and Gregory Sanchez were attacked. Sanchez was shot, then beaten. Domingo was bound and killed.", head="HOMICIDE  •  DOMINGO / SANCHEZ", lines=["Goleta, CA  •  Jul 27, 1981","Sanchez shot and beaten","Domingo bound and killed"])
seg("timeline", "And then, for almost five years, nothing. Until May 1986, when eighteen-year-old Janelle Cruz was killed while home alone in Irvine, while her family was on vacation in Mexico.", marks=[["DEC 1979","Goleta"],["MAR 1980","Ventura"],["AUG 1980","Dana Point"],["FEB 1981","Irvine"],["JUL 1981","Goleta"],["MAY 1986","Irvine"]])
seg("board", "Ten people murdered in Southern California. Police there called the killer the Original Night Stalker. And here is the terrible part: nobody connected him to the East Area Rapist up north.", cards=["ORIGINAL NIGHT STALKER","10 VICTIMS","SANTA BARBARA • VENTURA • ORANGE CO.","NOT LINKED TO EAR"])
seg("map", "Different counties. Different police departments. Different files in different cities. Agencies competed with each other, and often didn't share what they had. One man had attacked from Sacramento to Orange County, and the system saw two different monsters.", pins=[["Sacramento",1],["Goleta",1],["Ventura",1],["Dana Point",1],["Irvine",1]], focus="ca", title="ONE MAN  •  TWO NAMES")
seg("sketch", "After Janelle Cruz in 1986, the killer simply stopped. No more attacks. No more phone calls. No more poems. He disappeared.")

# ---------- CH5 ----------
chapter("Chapter Five", "The Long Silence")
seg("photos", "In January 1983, Joseph DeAngelo and his family had moved into a house on Canyon Oak Drive in Citrus Heights, the same Sacramento suburb where he'd once been caught shoplifting.", photos=[["house","Canyon Oak Drive"],["door","Family home, 1983"]])
seg("truck", "He found work as a truck mechanic at a supermarket distribution warehouse in Roseville. He would keep that job for twenty-seven years. He raised three daughters. He became a grandfather.")
seg("house", "Neighbours later said he was odd and kept to himself, and could sometimes be heard yelling and cursing in his driveway. But nobody imagined anything more. His name was never on any investigator's list.", day=True)
seg("timeline", "Meanwhile, the case went cold. Detectives retired. Files went into boxes. The victims grew older, and many of them were never sure if anyone was still looking.", marks=[["1986","Last murder"],["1990s","Case goes cold"],["2001","DNA link"],["2016","FBI reward"]])
seg("dna", "But a few investigators never let go. One of them was Paul Holes, a young criminalist in Contra Costa County, who found the old rape kits in storage in the 1990s and started testing them.")
seg("lab", "DNA technology was getting better every year. In 2001, labs finally compared the DNA from the northern rapes with DNA from the southern murders. It was a match. The East Area Rapist and the Original Night Stalker were the same man.", a="EAST AREA RAPIST", b="ORIGINAL NIGHT STALKER")
seg("board", "Investigators gave him a combined name: EARONS. Now they had his complete genetic profile. But a DNA profile is useless without a name to match it to, and his DNA was not in any criminal database. He had never been arrested for a serious crime.", cards=["EARONS","DNA PROFILE: COMPLETE","CODIS MATCH: NONE","NAME: UNKNOWN"])
seg("book", "Then a writer named Michelle McNamara became obsessed with the case. She spent years digging through files and interviewing detectives, and she gave the killer the name that finally stuck: the Golden State Killer.")
seg("book", "McNamara died in her sleep in 2016, before she could finish her book. It was completed by her husband, the comedian Patton Oswalt, and her research team, and published in February 2018 as I'll Be Gone in the Dark. It became a bestseller. The world was paying attention again.")
seg("newspaper", "In June 2016, the FBI and local agencies announced a renewed push, with a fifty-thousand-dollar reward. If he was still alive, the FBI said, the killer would now be somewhere between sixty and seventy-five years old.", head="FBI OFFERS $50,000 REWARD", sub="Renewed hunt for 1970s-80s serial killer")

# ---------- CH6 ----------
chapter("Chapter Six", "The Family Tree")
seg("dna", "Paul Holes had been hunting this man for over two decades. In 2017, he and FBI lawyer Steve Kramer tried something that had never been done in a case like this.")
seg("board", "Holes had chased other suspects before. Some leads had looked perfect, until the DNA said no. Each one was another dead end, another year gone. By 2018, he was preparing to retire with his biggest case unsolved.", cards=["SUSPECT: CLEARED","SUSPECT: CLEARED","SUSPECT: CLEARED","CASE: OPEN"])
seg("tree", "Consumer DNA tests had exploded in popularity. Millions of people were sending saliva samples to find long-lost relatives. Some uploaded their results to a free, public website called GEDmatch.", stage=0)
seg("tree", "The idea was simple, and controversial. Take the killer's DNA, upload it like any other user, and see who comes up as his relatives. You won't find him. But you might find his cousins.", stage=1)
seg("dna", "They brought in Barbara Rae-Venter, a retired patent lawyer turned genetic genealogist, who had used the same methods to help adopted people find their birth families.")
seg("tree", "The search returned more than a thousand genetic cousins, most of them very distant. Third cousins. Fourth cousins. People who shared a great-great-great-grandparent with the killer, back in the 1800s.", stage=2)
seg("tree", "So the team worked backwards. They traced those ancestors, then built the family trees forward again, generation by generation, branch by branch, looking for men of the right age who had lived in the right places.", stage=3)
seg("tree", "Rae-Venter noticed clues in the genetics. The killer was probably of Italian descent, and possibly prematurely bald. Slowly, the list shrank. Hundreds of men. Then dozens. Then six.", stage=4)
seg("board", "Witnesses back in the seventies had said the attacker had blue eyes. So investigators checked the driver's licence records for the six men. Only one had blue eyes.", cards=["SUSPECT 1: CLEARED","SUSPECT 2: CLEARED","SUSPECT 3: CLEARED","SUSPECT 4: CLEARED","SUSPECT 5: CLEARED","SUSPECT 6  EYES: BLUE"])
seg("reveal", "Around three in the morning on April 14th, 2018, Barbara Rae-Venter found the name that fit. A seventy-two-year-old man in Citrus Heights. A former police officer.", name="JOSEPH JAMES DeANGELO", info="AGE 72  •  CITRUS HEIGHTS, CA  •  FORMER POLICE OFFICER")
seg("map", "He had lived in Sacramento during the East Area Rapist attacks. He had worked as a cop ten miles from Visalia during the Ransacker burglaries. Every place on the map lined up.", pins=[["Exeter",1],["Visalia",1],["Auburn",1],["Citrus Heights",1]], focus="valley", title="EVERY PLACE LINES UP")

# ---------- CH7 ----------
chapter("Chapter Seven", "The Discarded Sample")
seg("surveil", "But a family tree is not proof. They needed his DNA. So detectives started following him.", stamp="SURVEILLANCE  •  APRIL 2018")
seg("evidence", "On April 18th, while DeAngelo was inside a store, an investigator swabbed the door handle of his car. The lab ran the sample. It matched the crime scene DNA.", items=[["car","Subject vehicle"],["swab","Car door handle swab"]])
seg("lab", "They wanted to be certain. A few days later, they collected a tissue he had thrown into the trash outside his home. Second sample. Second match.", a="CRIME SCENE DNA", b="DISCARDED TISSUE")
seg("surveil", "Prosecutors later said that the day before the arrest, DeAngelo weaved his motorcycle through freeway traffic and lost the detectives who were tailing him. Whether he noticed them or not, nobody knows.", stamp="SUBJECT LOST IN TRAFFIC")
seg("dna", "Paul Holes had officially retired just three weeks before the arrest. He had spent twenty-four years on this case. In the end, he was there to see it finished.")
seg("house", "The plan was to grab him outside, away from the house and the guns inside it. On April 24th, 2018, he stepped into his yard. A sheriff's fugitive team moved in.", day=True, caption="APRIL 24, 2018  •  ARREST")
seg("quote", "The monster who had terrified California for a decade offered no resistance. He looked shocked. And he told them he had a roast in the oven. The deputies said they would take care of it.", q="“I have a roast in the oven.”", who="JOSEPH DeANGELO, 72")
seg("interrogation", "At the station, he barely spoke to detectives. But left alone in the interrogation room, prosecutors later said, he began talking to himself, about someone he called Jerry.")
seg("interrogation", "According to the prosecutor who later wrote a book about the case, detectives even offered him a can of Dr Pepper, a soft drink investigators had linked to some old crime scenes. He didn't touch it.")
seg("quote", "He talked about Jerry as if Jerry were another person inside him, one who had made him do it. He said he had pushed Jerry out and had a happy life. And then:", q="“I didn't have the strength to push him out.”", who="ALONE IN THE INTERROGATION ROOM")
seg("quote", "And finally, according to prosecutors, three words that echoed forty years of fear.", q="“I did all that.”", who="AS REPORTED BY PROSECUTOR THIEN HO")
seg("interrogation", "Prosecutors believed it was a performance, an old man feigning confusion and a split personality to set up an insanity defence. On surveillance, he had seemed sharp and fully in control.")
seg("newspaper", "On April 25th, authorities announced the arrest. Sacramento's district attorney said they had found the needle in the haystack, and it was right here in Sacramento. By coincidence, it was National DNA Day.", head="'GOLDEN STATE KILLER' SUSPECT ARRESTED", sub="Ex-police officer, 72, identified through genealogy DNA")

# ---------- CH8 ----------
chapter("Chapter Eight", "Judgment")
seg("court", "In court, DeAngelo appeared in a wheelchair, slumped and silent, looking frail and confused. For two years, he said almost nothing.")
seg("court", "On June 29th, 2020, in the middle of the pandemic, his plea hearing was held in a university ballroom at Sacramento State, so that more than a hundred and fifty victims, relatives and observers could attend at a safe distance.", caption="SACRAMENTO STATE  •  JUNE 29, 2020")
seg("quote", "Wearing orange jail clothes and a plastic face shield, he listened as prosecutors read out his crimes, one by one. After each one, in a hushed, raspy voice, he answered.", q="“Guilty.”   “I admit.”", who="JUNE 29, 2020")
seg("file", "He pleaded guilty to thirteen murders and thirteen kidnappings. He also admitted to dozens of rapes that could no longer be prosecuted because the legal time limit had expired. In exchange, he avoided the death penalty.", head="PLEA AGREEMENT  •  PEOPLE v. DeANGELO", lines=["13 counts first-degree murder: GUILTY","13 counts kidnapping: GUILTY","Uncharged rapes: ADMITTED","Death penalty: WITHDRAWN"])
seg("court", "Gay and Bob Hardwick, who had been attacked in 1978, stood arm in arm and looked at him. Gay Hardwick said she could not recognise the hunched old man in the wheelchair as the person who had terrorised them forty-two years earlier.")
seg("court", "In August 2020, over several days, survivors and families took the microphone. Daughters and sons spoke of parents they never got to grow old with. Women who were attacked as teenagers spoke as grandmothers. Even his former fiancée gave a statement.")
seg("court", "His own family was not spared. His estranged wife had filed for divorce in 2019. One of his daughters wrote to the court describing him as the best father she could have had.")
seg("quote", "On August 21st, 2020, he finally spoke to the room.", q="“I'm truly sorry to everyone I've hurt.”", who="JOSEPH DeANGELO  •  AUG 21, 2020")
seg("cell", "The judge sentenced him to multiple consecutive life sentences, with no possibility of parole. Joseph James DeAngelo will die in prison.", txt="LIFE WITHOUT PAROLE")

# ---------- OUTRO ----------
chapter("Epilogue", "The Witnesses")
seg("tree", "The Golden State Killer case changed criminal investigation forever. It was the first public arrest made through genetic genealogy. Within two years, more than a hundred and fifty more suspects had been identified the same way.", stage=4)
seg("timeline", "Cold cases that had been dead for thirty, forty, fifty years were suddenly solvable. Not because a witness came forward, but because a distant cousin sent off a tube of saliva to learn about their ancestry.", marks=[["2018","GSK arrest"],["2019","Dozens solved"],["2020","150+ identified"],["TODAY","Hundreds"]])
seg("dna", "It also raised hard questions about privacy, and about who gets to search our DNA, and why. Those questions are still being argued today.")
seg("sketch", "For forty years, he believed he had gotten away with it. He built a quiet life, raised a family, cooked a roast on a Tuesday afternoon. But everything we touch leaves something behind.")
seg("title", "And sometimes, the witness who finally speaks up isn't a person at all. It's the truth, waiting patiently in a freezer, in a family tree, in the dark.", big="CASE CLOSED", small="THE GOLDEN STATE KILLER")
seg("end", "If you want more solved cases like this one, subscribe to Midnight Witness. A new case every night. And tell us in the comments: which case should we cover next?")
